 padding: 18px 38px;\n  border: 2px solid transparent;\n  text-transform: uppercase;\n  border-radius: 0px;\n  font-size: 14px;\n  line-height: 14px;\n  font-weight: 600;\n  box-shadow: rgb(153, 153, 153) 0px 0px 0px 0px;\n}\n.btn:focus {\n  outline: 0px;\n  border: 0px;\n  box-shadow: none;\n}\n\n.btn-main {\n  background: #f44336;\n  color: #fff;\n}\n.btn-main:hover {\n  color: #fff !important;\n  background: #000;\n}\n\n.btn-black {\n  background: #000;\n  color: #fff;\n}\n.btn-black:hover {\n  background: #f44336;\n  color: #fff;\n}\n\n.btn-white {\n  background: #fff;\n  color: #000;\n  border-color: #fff;\n}\n.btn-white:hover {\n  background: transparent;\n  color: #fff;\n}\n\na {\n  color: #000;\n  -webkit-transition: all 0.25s ease;\n  -moz-transition: all 0.25s ease;\n  -ms-transition: all 0.25s ease;\n  -o-transition: all 0.25s ease;\n  transition: all 0.25s ease;\n}\na:hover {\n  color: #f44336;\n  text-decoration: none;\n  outline: none;\n}\n\n.bg-primary {\n  background: #f44336 !important;\n}\n\n.bg-secondary {\n  background: #f7f7f7 !important;\n}\n\n.bg-extra {\n  background: #e8eefb !important;\n}\n\n.text-color {\n  color: #f44336;\n}\n\n.page-title h1 {\n  position: relative;\n  padding-bottom: 30px;\n}\n.page-title h1:after {\n  position: absolute;\n  content: \"\";\n  left: 50%;\n  bottom: 0px;\n  width: 40px;\n  height: 2px;\n  margin-left: -25px;\n  background: #f44336;\n}\n\n@media (max-width: 575px) {\n  h2, .h2 {\n    font-size: 32px;\n    line-height: 43px;\n  }\n}\n@media (max-width: 400px) {\n  h2, .h2 {\n    font-size: 32px;\n    line-height: 43px;\n  }\n}\n/* Typing hero */\n.cd-headline.clip span {\n  padding: 0;\n}\n\n.banner .cd-headline {\n  font-size: 56px;\n  line-height: 1.18;\n}\n\n.banner .cd-headline .cd-words-wrapper {\n  display: inline-block;\n  overflow: hidden;\n  vertical-align: top;\n}\n\n.banner-3 {\n  position: relative;\n}\n\n.banner {\n  position: relative;\n  overflow: hidden;\n  min-height: 650px;\n  display: flex;\n  align-items: center;\n}\n\n.banner-video {\n  position: absolute;\n  inset: 0;\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  z-index: 0;\n  opacity: 0.58;\n  filter: brightness(0.68) contrast(1.08) saturate(0.72);\n  transform: scale(1.015);\n}\n\n.banner-overlay {\n  position: absolute;\n  inset: 0;\n  z-index: 1;\n  background: linear-gradient(90deg, rgba(0, 0, 0, 0.82) 0%, rgba(0, 0, 0, 0.68) 48%, rgba(0, 0, 0, 0.48) 100%), linear-gradient(180deg, rgba(0, 0, 0, 0.3), rgba(0, 0, 0, 0.62));\n}\n\n.banner-content {\n  position: relative;\n  z-index: 2;\n}\n\n@media (max-width: 991px) {\n  .banner .cd-headline {\n    font-size: 44px;\n    line-height: 1.2;\n  }\n}\n@media (max-width: 575px) {\n  .banner {\n    min-height: 680px;\n  }\n  .banner .cd-headline {\n    font-size: 35px;\n  }\n}\n.main-nav .header-top-socials a {\n  text-transform: uppercase;\n  letter-spacing: 1px;\n  font-size: 14px;\n  padding: 20px 6px;\n}\n\n.navbar-nav .nav-link {\n  padding: 20px 15px !important;\n  text-transform: uppercase;\n  font-size: 14px;\n  letter-spacing: 1px;\n  font-weight: 700;\n}\n\nul.dropdown-menu {\n  background: rgb(21, 21, 21);\n  border-radius: 0px;\n  margin: 0px;\n  padding: 0px;\n}\n\nul.dropdown-menu > li > a, .navbar ul ul ul.dropdown-menu li .nav-link {\n  font-size: 12px;\n  line-height: 22px;\n  display: block;\n  position: relative;\n  z-index: 1;\n  padding-left: 15px;\n  -webkit-transition: all 0.3s ease-in-out;\n  transition: all 0.3s ease-in-out;\n  padding-top: 10px;\n  padding-bottom: 10px;\n  border-bottom: 1px solid #27243e;\n  color: #fff;\n  text-transform: uppercase;\n}\nul.dropdown-menu > li > a:hover, .navbar ul ul ul.dropdown-menu li .nav-link:hover {\n  color: #f44336;\n}\n\n.dropdown-item:focus, .dropdown-item:hover {\n  color: #fff;\n  text-decoration: none;\n  background-color: transparent;\n}\n\n.dropdown-menu {\n  border-radius: 0;\n  -moz-border-radius: 0;\n  -webkit-border-radius: 0;\n  -o-border-radius: 0;\n  -ms-bo