l .3s ease-in-out 0s;\n    -moz-transition: all .3s ease-in-out 0s;\n    -ms-transition: all .3s ease-in-out 0s;\n    -o-transition: all .3s ease-in-out 0s;\n    box-shadow: 0 6px 12px rgba(0,0,0,.175);\n    -webkit-box-shadow: 0 6px 12px rgba(0,0,0,.175);\n    -moz-box-shadow: 0 6px 12px rgba(0,0,0,.175);\n    -ms-box-shadow: 0 6px 12px rgba(0,0,0,.175);\n    -o-box-shadow: 0 6px 12px rgba(0,0,0,.175);\n\n}\n\n.dropdown:hover .dropdown-menu{\n\topacity: 1;\n\tvisibility:visible;\n\t-webkit-transform: scaleY(1);\n    -moz-transform: scaleY(1);\n    -ms-transform: scaleY(1);\n    -o-transform: scaleY(1);\n}\n\n\n@include mobile{\n    .navbar-nav .dropdown-menu {\n        position: absolute;\n    }\n\n    .banner .cd-headline {\n        font-size: 32px;\n        line-height: 42px;\n    }\n    .btn-group, .btn-group-vertical {\n        display: block;\n    }\n\n    .btn-group > .btn {\n        padding: 20px;\n    }\n}\n\n\n\n@include mobile-xs{\n    .navbar-nav .dropdown-menu {\n        position: absolute;\n    }\n    .banner .cd-headline {\n        font-size: 32px;\n        line-height: 42px;\n    }\n     .btn-group, .btn-group-vertical {\n        display: block;\n    }\n    .btn-group > .btn {\n        padding: 20px;\n    }\n}\n\n@include tablet{\n    .navbar-nav .dropdown-menu {\n        position: absolute;\n    }\n    .banner .cd-headline {\n        font-size: 32px;\n        line-height: 42px;\n    }\n     .btn-group, .btn-group-vertical {\n        display: block;\n    }\n    .btn-group > .btn {\n        padding: 20px;\n    }\n}\n@include desktop{\n    .navbar-nav .dropdown-menu {\n        position: absolute;\n    }\n    .banner .cd-headline {\n        font-size: 32px;\n        line-height: 42px;\n    }\n     .btn-group, .btn-group-vertical {\n        display: block;\n    }\n    .btn-group > .btn {\n        padding: 20px;\n    }\n}","\n\n// Portfolio\n// \n.portfolio{\n  padding-bottom: 100px;\n\n  .btn:focus,.btn:hover,.btn.focus.active{\n    box-shadow: none!impo