;\n}\n\n.embroidery-slider .carousel-control-prev,\n.embroidery-slider .carousel-control-next {\n  width: 6%;\n}\n\n.embroidery-service {\n  transition: all .3s ease;\n}\n\n.embroidery-service:hover {\n  transform: translateY(-5px);\n}\n\n.embroidery-service i {\n  font-size: 34px;\n}\n\n.embroidery-pricing {\n  background: #f8f8f8;\n}\n\n.pricing-card {\n  position: relative;\n  background: #fff;\n  padding: 42px 35px 35px;\n  border: 1px solid #eee;\n  text-align: center;\n  transition: all .3s ease;\n  box-shadow: 0 5px 25px rgba(0,0,0,.04);\n}\n\n.pricing-card:hover {\n  transform: translateY(-7px);\n  box-shadow: 0 12px 35px rgba(0,0,0,.09);\n}\n\n.pricing-card.featured {\n  border-top: 4px solid #f5b301;\n  transform: translateY(-8px);\n  box-shadow: 0 15px 40px rgba(0,0,0,.10);\n}\n\n.pricing-card .popular {\n  position: absolute;\n  top: 0;\n  left: 50%;\n  transform: translate(-50%, -50%);\n  background: #f5b301;\n  color: #111;\n  font-size: 10px;\n  font-weight: 700;\n  letter-spacing: 1px;\n  padding: 7px 15px;\n  white-space: nowrap;\n}\n\n.pricing-head > span {\n  font-size: 11px;\n  letter-spacing: 2px;\n  font-weight: 700;\n}\n\n.pricing-head h3 {\n  margin: 10px 0 18px;\n  font-size: 25px;\n}\n\n.price {\n  font-size: 44px;\n  line-height: 1;\n  font-weight: 700;\n  margin-bottom: 28px;\n}\n\n.price sup {\n  font-size: 18px;\n  vertical-align: top;\n  top: 12px;\n  position: relative;\n}\n\n.price small {\n  font-size: 12px;\n  font-weight: 400;\n  color: #888;\n}\n\n.pricing-card ul {\n  list-style: none;\n  padding: 0;\n  margin: 0 0 30px;\n  text-align: left;\n}\n\n.pricing-card li {\n  padding: 10px 0;\n  border-bottom: 1px solid #eee;\n  font-size: 14px;\n}\n\n.pricing-card li:before {\n  content: \"✓\";\n  margin-right: 10px;\n  font-weight: 700;\n}\n\n.btn-outline-main {\n  border: 1px solid #111;\n  color: #111;\n  padding: 11px 25px;\n}\n\n.btn-outline-main:hover {\n  color: #fff;\n  background: #111;\n}\n\n@media (max-width: 991px) {\n  .embroidery-hero h1 {\n    font-size: 44px;\n  }\n\n  .pricing-card.featured {\n    transform: none;\n  }\n}\n\n@media (max-width: 575px) {\n  .embroidery-hero {\n    min-height: 650px;\n  }\n\n  .embroidery-hero h1 {\n    font-size: 35px;\n  }\n\n  .embroidery-hero .hero-copy {\n    font-size: 16px;\n  }\n}\n\n/* Embroidery work */\n.embroidery-work {\n  padding-top: 100px;\n  padding-bottom: 80px;\n}\n\n.embroidery-filters {\n  justify-content: flex-end;\n  flex-wrap: wrap;\n}\n\n.embroidery-filters .btn {\n  margin-left: 18px;\n  padding-left: 0;\n  padding-right: 0;\n  border: 0;\n  background: transparent;\n}\n\n.embroidery-filters .btn.active {\n  color: #f5b301;\n}\n\n.embroidery-work .inner-box .image {\n  background: #f5f5f5;\n  min-height: 280px;\n}\n\n.embroidery-work .inner-box .image img {\n  aspect-ratio: 1 / 1;\n  object-fit: cover;\n}\n\n@media (max-width: 991px) {\n  .embroidery-filters {\n    justify-content: flex-start;\n  }\n\n  .embroidery-filters .btn {\n    margin-left: 0;\n    margin-right: 18px;\n  }\n}\n"]}